<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,nextTick} from 'vue'
const props=withDefaults(defineProps<{api:(url:string,method?:string,body?:unknown)=>Promise<any>;mode?:'tasks'|'accounts'}>(),{mode:'tasks'})
const emit=defineEmits<{ 'manage-accounts':[] }>()
type Account={id:string;name:string;provider:string;credential_id:string;secret?:string;has_secret?:boolean}
type Task={id:string;name:string;account_id:string;ipv4_domains:string[];ipv6_domains:string[];ipv4_url:string;ipv6_url:string;interval_seconds:number;ttl:string;enabled:boolean;state?:{running:boolean;message:string;result_known:boolean;checking:boolean;ipv4:string;ipv6:string;ipv4_result:string;ipv6_result:string;provider_requests:number;update_requests:number;last_check:string;last_finished:string;last_request:string;http_status:number;network_error:boolean;records?:{domain:string;type:string;result:string;message?:string}[]}}
const accounts=ref<Account[]>([]),tasks=ref<Task[]>([]),busy=ref(false),error=ref(''),notice=ref(''),kind=ref(''),editing=ref(false)
const dialog=ref<HTMLDialogElement>(),confirmation=ref<HTMLDialogElement>(),pending=ref<{kind:string;id:string;name:string}>()
const detailDialog=ref<HTMLDialogElement>(),detailID=ref('')
const history=ref<NonNullable<Task['state']>[]>([])
const selected=computed(()=>tasks.value.find(t=>t.id===detailID.value))
const attention=computed(()=>tasks.value.filter(t=>t.enabled&&['failed','ip_failed','invalid_domain'].some(x=>[t.state?.ipv4_result,t.state?.ipv6_result].includes(x))).length)
const account=ref<Account>(freshAccount()),task=ref<Task>(freshTask()),v4=ref(''),v6=ref(''),family=ref('A')
const providers=[['dnspod','DNSPod.cn（ID / Token）'],['tencentcloud','腾讯云 DNSPod'],['cloudflare','Cloudflare'],['alidns','阿里云 DNS']]
function uid(){return crypto.randomUUID().replaceAll('-','')}
function freshAccount():Account{return {id:uid(),name:'',provider:'dnspod',credential_id:'',secret:''}}
function freshTask():Task{return {id:uid(),name:'',account_id:'',ipv4_domains:[],ipv6_domains:[],ipv4_url:'https://api4.ipify.org',ipv6_url:'https://api6.ipify.org',interval_seconds:300,ttl:'600',enabled:false}}
function date(value?:string){return !value||value.startsWith('0001-')?'—':new Date(value).toLocaleString()}
function clock(value?:string){return !value||value.startsWith('0001-')?'—':new Date(value).toLocaleTimeString('zh-CN',{hour12:false})}
function day(value?:string){return !value||value.startsWith('0001-')?'尚未检查':new Date(value).toLocaleDateString('zh-CN')}
function result(value?:string){return ({disabled:'未启用',ip_failed:'IP 获取失败',invalid_domain:'域名无效',unchanged:'未变化',success:'更新成功',failed:'请求失败'} as Record<string,string>)[value||'']||'等待检查'}
function summary(t:Task){if(!t.enabled)return {text:'已停用',tone:'neutral'};if(t.state?.checking)return {text:'检查中',tone:'pending'};const r=[t.state?.ipv4_result,t.state?.ipv6_result];if(r.includes('ip_failed'))return {text:'IP 获取失败',tone:'error'};if(r.includes('failed')||r.includes('invalid_domain'))return {text:'同步失败',tone:'error'};if(r.includes('success'))return {text:'更新成功',tone:'success'};if(t.state?.result_known)return {text:'无需更新',tone:'success'};return {text:t.state?.running?'等待检查':'未运行',tone:'neutral'}}
function requestSummary(t:Task){if(t.state?.update_requests)return `已发起 ${t.state.update_requests} 次更新`;if(t.state?.result_known)return '未发起更新';return '等待检查结果'}
function records(t:Task){return [...t.ipv4_domains.map(domain=>({domain,type:'A'})),...t.ipv6_domains.map(domain=>({domain,type:'AAAA'}))]}
async function showDetails(t:Task){detailID.value=t.id;history.value=[];await nextTick();detailDialog.value?.showModal();await perform(loadHistory)}
let noticeTimer:ReturnType<typeof setTimeout>
function notify(text:string){notice.value=text;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>notice.value='',5000)}
function accountName(id:string){return accounts.value.find(a=>a.id===id)?.name||id}
async function loadHistory(){if(detailID.value){const x=await props.api('/dns/tasks/'+detailID.value+'/history');history.value=x.history}}
async function load(){if(props.mode==='accounts'){const x=await props.api('/dns/accounts');accounts.value=x.accounts;return}const x=await props.api('/dns/');accounts.value=x.accounts;tasks.value=x.tasks;if(detailDialog.value?.open)await loadHistory()}
async function perform(fn:()=>Promise<void>){busy.value=true;error.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
async function openAccount(a?:Account){error.value='';kind.value='accounts';editing.value=!!a;account.value=a?{...a,secret:''}:freshAccount();await nextTick();dialog.value?.showModal();dialog.value?.querySelector<HTMLInputElement>('input')?.focus()}
async function openTask(t?:Task){error.value='';kind.value='tasks';editing.value=!!t;task.value=t?{...t}:freshTask();task.value.account_id ||= accounts.value[0]?.id||'';v4.value=task.value.ipv4_domains.join(', ');v6.value=task.value.ipv6_domains.join(', ');family.value=v6.value?(v4.value?'both':'AAAA'):'A';await nextTick();dialog.value?.showModal();dialog.value?.querySelector<HTMLInputElement>('input')?.focus()}
async function save(){await perform(async()=>{if(kind.value==='accounts'){const a=account.value;await props.api('/dns/accounts/'+a.id,'PUT',{id:a.id,name:a.name,provider:a.provider,credential_id:a.credential_id,secret:a.secret||''});account.value=freshAccount()}else{const {state,...body}=task.value;body.ipv4_domains=family.value==='AAAA'?[]:v4.value.split(/[,\s]+/).filter(Boolean);body.ipv6_domains=family.value==='A'?[]:v6.value.split(/[,\s]+/).filter(Boolean);await props.api('/dns/tasks/'+body.id,'PUT',body)}dialog.value?.close();await load();notify('已保存')})}
async function toggle(t:Task){await perform(async()=>{const {state,...body}=t;await props.api('/dns/tasks/'+t.id,'PUT',{...body,enabled:!t.enabled});await load()})}
async function run(t:Task){await perform(async()=>{await props.api('/dns/tasks/'+t.id+'/run','POST');notify('已安排检查，结果将自动更新');await load()})}
function askDelete(k:string,id:string,name:string){error.value='';pending.value={kind:k,id,name};confirmation.value?.showModal()}
async function remove(){await perform(async()=>{const p=pending.value!;await props.api((p.kind==='accounts'?'/dns/accounts/':'/dns/tasks/')+p.id,'DELETE');confirmation.value?.close();await load()})}
let refreshTimer:ReturnType<typeof setInterval>
onMounted(()=>{perform(load);refreshTimer=setInterval(()=>{if(!dialog.value?.open&&!confirmation.value?.open&&!busy.value)load().catch(()=>{})},15000)})
onUnmounted(()=>{clearInterval(refreshTimer);clearTimeout(noticeTimer)})
</script>
<template>
<section class="card manager">
  <template v-if="mode==='tasks'"><div class="section-head"><div><h2>动态 DNS</h2><p class="overview">{{tasks.length}} 个任务<span>·</span>{{tasks.filter(t=>t.enabled).length}} 个已启用<span v-if="attention" class="attention">· {{attention}} 个需关注</span></p></div><div class="small-actions"><button class="secondary" :disabled="busy" @click="perform(load)">刷新</button><button :disabled="busy||!accounts.length" @click="openTask()">＋ 添加任务</button></div></div>
  <div v-if="tasks.length" class="proxy-table-wrap" tabindex="0" aria-label="DDNS 任务，窄屏可横向滚动">
    <table class="ddns-table"><colgroup><col style="width:16%"><col style="width:22%"><col style="width:19%"><col style="width:15%"><col style="width:13%"><col style="width:15%"></colgroup>
      <thead><tr><th scope="col">任务</th><th scope="col">域名</th><th scope="col">公网 IP</th><th scope="col">同步结果</th><th scope="col">最近检查</th><th scope="col" class="action-cell">操作</th></tr></thead>
      <tbody><tr v-for="t in tasks" :key="t.id">
        <td><strong class="task-name">{{t.name}}</strong><div class="subtext"><span :class="['process-dot',{on:t.enabled&&t.state?.running}]"></span>{{!t.enabled?'已停用':t.state?.running?'运行中':'未运行'}}</div></td>
        <td><div v-for="r in records(t)" :key="r.type+r.domain" class="record-line"><span class="domain-name">{{r.domain}}</span><span class="record-type">{{r.type}}</span></div></td>
        <td><div v-if="t.ipv4_domains.length" class="ip-line"><span class="ip-address">{{t.state?.ipv4||'—'}}</span><span class="ip-family">IPv4</span></div><div v-if="t.ipv6_domains.length" class="ip-line"><span class="ip-address">{{t.state?.ipv6||'—'}}</span><span class="ip-family">IPv6</span></div></td>
        <td><span :class="['sync-badge',summary(t).tone]">{{summary(t).text}}</span><div class="subtext">{{requestSummary(t)}}</div></td>
        <td><span class="check-clock">{{clock(t.state?.last_check)}}</span><div class="subtext">{{day(t.state?.last_check)}}</div></td>
        <td class="action-cell"><div class="row-actions"><button class="text-button" :disabled="busy" @click="openTask(t)">编辑</button><button class="text-button" :disabled="busy||!t.enabled" @click="run(t)">检查</button><button class="text-button" :disabled="busy" @click="showDetails(t)">详情</button></div></td>
      </tr></tbody>
    </table>
  </div>
  <p v-else class="empty">还没有任务。请先添加 DNS 账号，再创建 DDNS 任务。</p>
  <div class="account-link"><span>{{accounts.length}} 个 DNS 账号可用</span><button class="text-button" @click="emit('manage-accounts')">管理 DNS 账号 →</button></div></template>
  <template v-else><div class="section-head"><div><h2>DNS 账号</h2><p class="overview">供动态 DNS 和证书 DNS-01 共用</p></div><button :disabled="busy" @click="openAccount()">＋ 添加账号</button></div><div class="accounts-body"><article v-for="a in accounts" :key="a.id"><div><strong>{{a.name}}</strong><p>{{providers.find(p=>p[0]===a.provider)?.[1]}} · 密钥已保存</p></div><div class="small-actions"><button class="secondary" :disabled="busy" @click="openAccount(a)">编辑</button><button class="danger" :disabled="busy" @click="askDelete('accounts',a.id,a.name)">删除</button></div></article><p v-if="!accounts.length" class="empty">添加一次账号，DDNS 和证书都可以引用。</p></div><p class="detail-note">账号被任务、证书或已应用配置引用时不能删除。修改密钥后，DDNS 自动重载；证书续期会使用新密钥，代理不接收 DNS 凭据。</p></template>
  <p v-if="notice" class="inline-notice" role="status">{{notice}}</p><p v-if="error&&!dialog?.open&&!confirmation?.open&&!detailDialog?.open" class="form-error" role="alert">{{error}}</p>
</section>
<dialog ref="detailDialog" class="editor-dialog status-dialog" aria-labelledby="status-title" @cancel="busy&&$event.preventDefault()">
  <template v-if="selected"><div class="dialog-head"><h2 id="status-title">任务详情</h2><button class="icon-button" aria-label="关闭任务详情" :disabled="busy" @click="detailDialog?.close()">×</button></div>
    <div class="detail-heading"><strong>{{selected.name}}</strong><span :class="['sync-badge',summary(selected).tone]">{{summary(selected).text}}</span></div><p class="detail-message">{{selected.state?.message||'等待首次检查'}}</p>
    <dl class="status-grid"><div><dt>服务商账号</dt><dd>{{accountName(selected.account_id)}}</dd></div><div><dt>检查间隔 / TTL</dt><dd>{{selected.interval_seconds}} 秒 / {{selected.ttl}} 秒</dd></div><div><dt>检查开始</dt><dd>{{date(selected.state?.last_check)}}</dd></div><div><dt>检查完成</dt><dd>{{date(selected.state?.last_finished)}}</dd></div><div><dt>本轮接口请求（含查询）</dt><dd>{{selected.state?.provider_requests||0}} 次</dd></div><div><dt>本轮更新请求</dt><dd>{{selected.state?.update_requests||0}} 次</dd></div><div><dt>最近服务商请求</dt><dd>{{date(selected.state?.last_request)}}</dd></div><div><dt>最近请求响应</dt><dd>{{selected.state?.network_error?'网络请求失败':selected.state?.http_status?'HTTP '+selected.state.http_status:'尚无请求'}}</dd></div></dl>
    <div class="family-detail" v-if="selected.ipv4_domains.length"><h3>IPv4 · A <span>{{result(selected.state?.ipv4_result)}}</span></h3><p class="detail-ip">{{selected.state?.ipv4||'尚未获取 IP'}}</p><p class="subtext">{{selected.ipv4_domains.join('、')}}</p></div><div class="family-detail" v-if="selected.ipv6_domains.length"><h3>IPv6 · AAAA <span>{{result(selected.state?.ipv6_result)}}</span></h3><p class="detail-ip">{{selected.state?.ipv6||'尚未获取 IP'}}</p><p class="subtext">{{selected.ipv6_domains.join('、')}}</p></div>
    <div v-if="selected.state?.records?.length" class="family-detail"><h3>各域名结果</h3><p v-for="r in selected.state.records" :key="r.type+':'+r.domain" class="subtext">{{r.domain}} · {{r.type}} · {{result(r.result)}}<br v-if="r.message"><span v-if="r.message">{{r.message}}</span></p></div>
    <div class="family-detail"><h3>检查／更新历史（最近 100 次）</h3><p class="subtext">记录保存在本机，重启后保留。</p><div style="max-height:260px;overflow:auto"><p v-if="!history.length" class="subtext">尚无检查记录</p><div v-for="(h,i) in history" :key="i" class="family-detail"><p class="subtext">{{date(h.last_finished)}} · 查询及更新 {{h.provider_requests}} 次 / 更新 {{h.update_requests}} 次</p><p class="detail-message">{{h.message}}</p><p class="subtext">IPv4：{{h.ipv4||'—'}} · {{result(h.ipv4_result)}}<br>IPv6：{{h.ipv6||'—'}} · {{result(h.ipv6_result)}}</p></div></div></div>
    <p class="detail-note">更新请求表示尝试提交；更新成功以服务商返回结果为准。</p><p v-if="error" class="form-error" role="alert">{{error}}</p>
    <div class="detail-footer"><button class="danger" :disabled="busy" @click="detailDialog?.close();askDelete('tasks',selected.id,selected.name)">删除任务</button><div class="small-actions"><button class="secondary" :disabled="busy" @click="toggle(selected)">{{selected.enabled?'停用任务':'启用任务'}}</button><button :disabled="busy" @click="detailDialog?.close()">关闭</button></div></div>
  </template>
</dialog>
<dialog ref="dialog" class="editor-dialog" :aria-label="kind==='accounts'?'服务商账号':'DDNS 任务'" @cancel="busy&&$event.preventDefault()"><div class="dialog-head"><h2>{{editing?'编辑':'添加'}}{{kind==='accounts'?'服务商账号':' DDNS 任务'}}</h2><button class="icon-button" aria-label="关闭 DDNS 弹窗" :disabled="busy" @click="dialog?.close()">×</button></div><form @submit.prevent="save"><template v-if="kind==='accounts'"><label>账号名称<input v-model="account.name" placeholder="我的 DNSPod" required></label><label>DNS 服务商<select v-model="account.provider"><option v-for="p in providers" :value="p[0]">{{p[1]}}</option></select></label><label v-if="account.provider!=='cloudflare'">{{account.provider==='dnspod'?'Token ID':'AccessKey ID / SecretId'}}<input v-model="account.credential_id" autocomplete="off" required></label><label>{{account.provider==='cloudflare'?'API Token':'Token / SecretKey'}}<input v-model="account.secret" type="password" autocomplete="new-password" :placeholder="editing?'留空保留已有密钥':'填写服务商密钥'" :required="!editing"></label><p class="muted">密钥加密保存，不会回显。DDNS 使用 A/AAAA 权限；证书验证需要 TXT 查询、创建和删除权限。</p></template><template v-else><label>任务名称<input v-model="task.name" required></label><label>服务商账号<select v-model="task.account_id" required><option value="">请选择账号</option><option v-for="a in accounts" :value="a.id">{{a.name}}</option></select></label><label>记录类型<select v-model="family"><option value="A">IPv4 · A</option><option value="AAAA">IPv6 · AAAA</option><option value="both">IPv4 + IPv6</option></select></label><template v-if="family!=='AAAA'"><label>IPv4 域名（逗号分隔）<input v-model="v4" placeholder="example.com, *.example.com" required></label><label>IPv4 公网 IP 查询接口<input v-model="task.ipv4_url" type="url" required></label></template><template v-if="family!=='A'"><label>IPv6 域名（逗号分隔）<input v-model="v6" placeholder="example.com, *.example.com" required></label><label>IPv6 公网 IP 查询接口<input v-model="task.ipv6_url" type="url" required></label></template><div class="fields"><label>更新间隔（秒）<input v-model.number="task.interval_seconds" type="number" min="60" max="86400" required></label><label>TTL（秒）<input v-model="task.ttl" type="number" min="1" max="86400" required></label></div><label class="check"><input v-model="task.enabled" type="checkbox">保存后启用</label><p class="muted">启用后自动检查并更新解析记录；不存在时创建，TTL 用于新记录。现有记录保留 TTL 和线路等属性。</p></template><p v-if="error" class="form-error" role="alert">{{error}}</p><div class="dialog-actions"><button type="button" class="secondary" :disabled="busy" @click="dialog?.close()">取消</button><button :disabled="busy">{{kind==='accounts'?'保存账号':'保存任务'}}</button></div></form></dialog>
<dialog ref="confirmation" class="delete-dialog" aria-label="确认删除" @cancel="busy&&$event.preventDefault()"><h2>确认删除</h2><p>确定删除「{{pending?.name}}」？</p><p class="muted">删除任务会停止本应用管理的进程，DNS 服务商上的记录保留。</p><p v-if="error" class="form-error">{{error}}</p><div class="dialog-actions"><button class="secondary" :disabled="busy" @click="confirmation?.close()">取消</button><button class="danger" :disabled="busy" @click="remove">确认删除</button></div></dialog>
</template>
<style scoped>
.manager{margin-bottom:24px}.account-link{border-top:1px solid #e8eef0;margin-top:24px;padding-top:16px;display:flex;justify-content:space-between;align-items:center;font-size:12px;color:#758594}.overview{display:flex;gap:10px;color:#758594;font-size:13px;margin:9px 0 0}.attention{color:#b45142}
.ddns-table{width:100%;min-width:1080px;border-collapse:collapse;text-align:left;table-layout:fixed}.ddns-table th{background:#f5f8fa;color:#71808e;font-size:12px;font-weight:500;padding:13px 16px;border-bottom:1px solid #e6ecef}.ddns-table td{padding:20px 16px;border-bottom:1px solid #edf1f3;vertical-align:middle;font-size:13px;overflow-wrap:anywhere}.ddns-table tbody tr:last-child td{border-bottom:0}.ddns-table tbody tr:hover{background:#fafcfc}
.task-name{font-size:14px;display:block;line-height:1.5}.subtext{color:#7b8a97;font-size:12px;margin-top:7px;line-height:1.5}.process-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#b4bfc8;margin-right:6px;vertical-align:middle}.process-dot.on{background:#258a75}.record-line,.ip-line{display:flex;align-items:baseline;gap:8px;margin:4px 0}.domain-name{font-weight:600;line-height:1.6}.record-type{font-size:10px;color:#758594;background:#f0f4f6;border-radius:4px;padding:2px 5px;flex-shrink:0}.ip-address,.detail-ip{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;line-height:1.6;overflow-wrap:anywhere}.ip-family{font-size:10px;color:#8c99a4;flex-shrink:0}.sync-badge{display:inline-flex;padding:4px 9px;border-radius:6px;font-size:12px;white-space:nowrap}.sync-badge.success{background:#e7f3ee;color:#247a62}.sync-badge.error{background:#fff0ed;color:#b64c3c}.sync-badge.pending{background:#eaf1fb;color:#4774ad}.sync-badge.neutral{background:#f0f3f5;color:#7a8792}.check-clock{font-variant-numeric:tabular-nums;font-size:14px}.action-cell{text-align:right}.row-actions{display:flex;justify-content:flex-end;gap:14px;white-space:nowrap}.text-button{padding:4px 0;background:transparent;color:#226f66;font-size:13px;border-radius:3px}.text-button:hover{background:#e7f3ef}.text-button:disabled{color:#a0aab2;background:transparent}
.accounts-section{border-top:1px solid #e8eef0;margin-top:24px;padding-top:18px}.accounts-section>summary{display:flex;justify-content:space-between;align-items:center;cursor:pointer;font-size:14px;font-weight:600;list-style:none;padding:3px 0}.accounts-section>summary::-webkit-details-marker{display:none}.accounts-section>summary>span:first-child:before{content:'›';display:inline-block;margin-right:10px;color:#82918d;transition:transform .15s}.accounts-section[open]>summary>span:first-child:before{transform:rotate(90deg)}.account-count{margin-left:6px;background:#eef3f4;padding:2px 7px;border-radius:5px;color:#7b8a97;font-size:12px}.account-hint{font-size:12px;font-weight:400;color:#8a98a4}.accounts-body{padding-top:16px}.account-toolbar{display:flex;justify-content:flex-end}.accounts-body article{padding:16px 0}.accounts-body article:last-child{border-bottom:0}.accounts-body article strong{font-size:14px}.accounts-body article p{font-size:12px;margin:6px 0 0}.inline-notice{color:#246f60;font-size:13px;margin:16px 0 0}.status-dialog{width:min(660px,calc(100vw - 40px))}.detail-heading{display:flex;align-items:center;gap:12px;margin:20px 0 8px}.detail-heading strong{font-size:17px}.detail-message{font-size:13px;color:#758594}.status-grid{display:grid;grid-template-columns:1fr 1fr;gap:22px 24px;margin:24px 0}.status-grid dt{font-size:12px;color:#7b8a97;margin-bottom:6px}.status-grid dd{font-size:13px;margin:0;overflow-wrap:anywhere}.family-detail{border-top:1px solid #edf1f3;padding:16px 0 0;margin-top:16px}.family-detail h3{font-size:13px;margin:0}.family-detail h3 span{font-weight:400;color:#758594;margin-left:12px}.detail-ip{font-size:15px;margin:8px 0 0}.detail-note{font-size:12px;color:#8b99a4;margin-top:22px}.detail-footer{border-top:1px solid #e7edf0;padding-top:20px;margin-top:24px;display:flex;align-items:center;justify-content:space-between;gap:12px}@media(max-width:600px){.section-head{align-items:flex-start;gap:12px}.overview{font-size:12px;gap:6px}.account-hint{display:none}.status-grid{gap:18px 12px}.detail-footer{flex-wrap:wrap}.ip-line{flex-wrap:wrap}}
</style>

